input.command:
python3 - <<'E'
p='bookly/app.js'
s=open(p).read()
s=s.replace('''  // TODO S02: one button per slot
''','''  if (!list.length) return;
  const grid = document.createElement("div");
  grid.className = "slot-grid";
  list.forEach((t) => {
    const b = document.createElement("button");
    b.className = "slot";
    b.type = "button";
    b.textContent = t;
    grid.appendChild(b);
  });
  el.appendChild(grid);
''')
open(p,'w').write(s)
p='bookly/index.html'
s=open(p).read()
s=s.replace('<h1>Book a time with Dana</h1>','<h1>Book with Dana</h1>\n  <p class="lede">Grab a time before someone else does.</p>')
s=s.replace('    <!-- S02: the slot grid goes here. See .skillator/clone/recon.md FL01 -->\n','    <!-- S02: slot buttons are rendered into .slots by app.js -->\n')
open(p,'w').write(s)
open('bookly/styles.css','a').write('''.lede { color: var(--text-muted); }
.slot-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; }
.slot { background: var(--accent); color: var(--on-accent); border: 0; border-radius: 999px; padding: 10px 14px; font: inherit; cursor: pointer; }
.slot:hover { filter: brightness(1.1); }
.slot:focus-visible { outline: 2px solid var(--text); outline-offset: 2px; }
.slot:disabled { opacity: .4; cursor: not-allowed; }
''')
E
sed -i 's/^- \[x\] F2.*/&\n- [x] F3 — S02 slot grid: one pill button per slot, 4-column grid, own tokens/' TICKETS.md
git diff --stat

